import { useState } from 'react';
import {
  JxCard,
  JxStack,
  JxHeading,
  JxText,
  JxBadge,
  JxDivider,
  JxSegmentedControl,
  JxSegmentedControlItem,
  JxSlider,
  JxSwitch,
  JxSelect,
  JxSelectOption,
} from '@jinx-ui/react';

type Theme = 'brutal' | 'glass' | 'minimal';
type FontFamily = 'system' | 'serif' | 'mono';

export interface AppearanceSettingsValue {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: FontFamily;
}

interface AppearanceSettingsProps {
  onChange?: (value: AppearanceSettingsValue) => void;
}

const THEME_LABELS: Record<Theme, string> = {
  brutal: 'Brutal',
  glass: 'Glass',
  minimal: 'Minimal',
};

const FONT_OPTIONS: { value: FontFamily; label: string }[] = [
  { value: 'system', label: 'Системный' },
  { value: 'serif', label: 'С засечками' },
  { value: 'mono', label: 'Моноширинный' },
];

export default function AppearanceSettings({ onChange }: AppearanceSettingsProps) {
  const [theme, setTheme] = useState<Theme>('brutal');
  const [scale, setScale] = useState(100);
  const [dense, setDense] = useState(false);
  const [font, setFont] = useState<FontFamily>('system');

  const emit = (next: Partial<AppearanceSettingsValue>) => {
    onChange?.({
      theme: next.theme ?? theme,
      scale: next.scale ?? scale,
      dense: next.dense ?? dense,
      font: next.font ?? font,
    });
  };

  const handleThemeChange = (next: Theme) => {
    setTheme(next);
    emit({ theme: next });
  };

  const handleScaleChange = (next: number) => {
    setScale(next);
    emit({ scale: next });
  };

  const handleDenseChange = (next: boolean) => {
    setDense(next);
    emit({ dense: next });
  };

  const handleFontChange = (next: FontFamily) => {
    setFont(next);
    emit({ font: next });
  };

  return (
    <JxCard className="jx-p-lg">
      <JxStack direction="row" align="center" justify="space-between" className="jx-mb-md">
        <JxHeading level={2}>Внешний вид</JxHeading>
        <JxBadge variant="outline">{THEME_LABELS[theme]}</JxBadge>
      </JxStack>

      <JxStack direction="column" gap="lg">
        <JxStack direction="column" gap="sm">
          <JxText as="label" size="sm" weight="medium">
            Тема
          </JxText>
          <JxSegmentedControl value={theme} onChange={(value) => handleThemeChange(value as Theme)}>
            <JxSegmentedControlItem value="brutal">Brutal</JxSegmentedControlItem>
            <JxSegmentedControlItem value="glass">Glass</JxSegmentedControlItem>
            <JxSegmentedControlItem value="minimal">Minimal</JxSegmentedControlItem>
          </JxSegmentedControl>
        </JxStack>

        <JxStack direction="column" gap="sm">
          <JxStack direction="row" align="center" justify="space-between">
            <JxText as="label" size="sm" weight="medium" htmlFor="appearance-scale">
              Масштаб интерфейса
            </JxText>
            <JxText size="sm" tone="muted">
              {scale}%
            </JxText>
          </JxStack>
          <JxSlider
            id="appearance-scale"
            min={80}
            max={140}
            step={5}
            value={scale}
            onChange={(value: number) => handleScaleChange(value)}
          />
        </JxStack>

        <JxStack direction="row" align="center" justify="space-between">
          <JxStack direction="column" gap="none">
            <JxText as="label" size="sm" weight="medium" htmlFor="appearance-dense">
              Плотная вёрстка
            </JxText>
            <JxText size="xs" tone="muted">
              Меньше отступов между элементами
            </JxText>
          </JxStack>
          <JxSwitch
            id="appearance-dense"
            checked={dense}
            onChange={(checked: boolean) => handleDenseChange(checked)}
          />
        </JxStack>

        <JxDivider />

        <JxStack direction="column" gap="sm">
          <JxText size="sm" weight="medium" tone="muted">
            Ещё
          </JxText>
          <JxStack direction="column" gap="sm">
            <JxText as="label" size="sm" weight="medium" htmlFor="appearance-font">
              Шрифт
            </JxText>
            <JxSelect id="appearance-font" value={font} onChange={(value) => handleFontChange(value as FontFamily)}>
              {FONT_OPTIONS.map((option) => (
                <JxSelectOption key={option.value} value={option.value}>
                  {option.label}
                </JxSelectOption>
              ))}
            </JxSelect>
          </JxStack>
        </JxStack>
      </JxStack>
    </JxCard>
  );
}

